methods:
@Builder
  private pageAction(label: string, enabled: boolean, action: () => void) {
    Text(label)
      .fontFamily(TYPE_APP_SMALL_LABEL.fontFamily)
      .fontWeight(TYPE_APP_SMALL_LABEL.fontWeight)
      .fontSize(TYPE_APP_SMALL_LABEL.fontSizeFp)
      .fontColor(enabled ? readerAppColor('TOK_ON_PRIMARY', this.appThemeScheme) : readerAppColor('TOK_MUTED', this.appThemeScheme))
      .backgroundColor(enabled ? readerAppColor('app.action.fill', this.appThemeScheme) : readerAppColor('app.DiscoverPage.CHIP_BG', this.appThemeScheme))
      .padding({ left: TOK_SPACE_SM, right: TOK_SPACE_SM, top: 8, bottom: 8 })
      .borderRadius(999)
      .opacity(this.presentation.loading ? 0.6 : 1)
      .onClick((): void => {
        if (enabled && !this.presentation.loading) action();
      });
  }

@Builder
  private statusTab(label: string, mode: RssMode) {
    Stack({ alignContent: Alignment.Center }) {
      Text(label)
        .fontFamily(TYPE_APP_COMPACT_PRIMARY_ACTION.fontFamily)
        .fontWeight(TYPE_APP_COMPACT_PRIMARY_ACTION.fontWeight)
        .fontSize(TYPE_APP_COMPACT_PRIMARY_ACTION.fontSizeFp)
        .fontColor(this.activeMode === mode ? readerAppColor('TOK_ON_PRIMARY', this.appThemeScheme) : readerAppColor('app.RssPage.statusTab.fontColor.FF564D44', this.appThemeScheme))
        .textAlign(TextAlign.Center)
        .maxLines(1);
    }
    .height(30)
    .padding({ left: TOK_SPACE_CONTROL_INLINE, right: TOK_SPACE_CONTROL_INLINE })
    .backgroundColor(this.activeMode === mode ? readerAppColor('app.action.fill', this.appThemeScheme) : readerAppColor('app.RssPage.SOFT_PILL_BG', this.appThemeScheme))
    .borderRadius(999)
    .responseRegion({ x: 0, y: -7, width: '100%', height: 44 })
    .onClick((): void => this.onModeRequested(mode));
  }

@Builder
  private stateButtons(primaryLabel: string, primaryAction: () => void) {
    Row({ space: TOK_SPACE_CONTROL_INLINE }) {
      Stack({ alignContent: Alignment.Center }) {
        Text(primaryLabel)
          .fontFamily(TYPE_RSS_STATE_ACTION.fontFamily)
          .fontWeight(TYPE_RSS_STATE_ACTION.fontWeight)
          .fontSize(TYPE_RSS_STATE_ACTION.fontSizeFp)
          .fontColor(readerAppColor('TOK_ON_PRIMARY', this.appThemeScheme))
          .maxLines(1);
      }
      .width(88)
      .height(36)
      .backgroundColor(readerAppColor('app.action.fill', this.appThemeScheme))
      .borderRadius(999)
      .responseRegion({ x: 0, y: -4, width: '100%', height: 44 })
      .onClick((): void => primaryAction());

      Stack({ alignContent: Alignment.Center }) {
        Text('订阅管理')
          .fontFamily(TYPE_RSS_STATE_ACTION.fontFamily)
          .fontWeight(TYPE_RSS_STATE_ACTION.fontWeight)
          .fontSize(TYPE_RSS_STATE_ACTION.fontSizeFp)
          .fontColor(readerAppColor('TOK_PRIMARY_TEXT', this.appThemeScheme))
          .maxLines(1);
      }
      .width(88)
      .height(36)
      .backgroundColor(readerAppColor('TOK_PRIMARY_SOFT', this.appThemeScheme))
      .borderRadius(999)
      .responseRegion({ x: 0, y: -4, width: '100%', height: 44 })
      .onClick((): void => this.onManage());
    }
    .margin({ top: 20 })
    .alignItems(VerticalAlign.Center);
  }

@Builder
  private sourceCard() {
    Row({ space: TOK_SPACE_XS }) {
      Stack({ alignContent: Alignment.Center }) {
        Image((this.appThemeScheme === 'night' ? $r('app.media.rss_source_theme_night') : $r('app.media.rss_source'))).width(20).height(20);
      }
      .width(32)
      .height(32)
      .backgroundColor(readerAppColor('TOK_PRIMARY_BG', this.appThemeScheme))
      .borderRadius(16);

      Column({ space: 3 }) {
        Text(this.subscription.title)
          .width('100%')
          .fontFamily(TYPE_RSS_SOURCE_TITLE.fontFamily)
          .fontWeight(TYPE_RSS_SOURCE_TITLE.fontWeight)
          .fontSize(TYPE_RSS_SOURCE_TITLE.fontSizeFp)
          .fontColor(readerAppColor('TOK_INK', this.appThemeScheme))
          .maxLines(1)
          .textOverflow({ overflow: TextOverflow.Ellipsis });
        Text(this.itemMeta())
          .width('100%')
          .fontFamily(TYPE_RSS_META.fontFamily)
          .fontWeight(TYPE_RSS_META.fontWeight)
          .fontSize(TYPE_RSS_META.fontSizeFp)
          .fontColor(readerAppColor('TOK_MUTED', this.appThemeScheme))
          .maxLines(1)
          .textOverflow({ overflow: TextOverflow.Ellipsis });
      }
      .layoutWeight(1)
      .alignItems(HorizontalAlign.Start);

      Text('查看源')
        .height(28)
        .padding({ left: 9, right: 9 })
        .fontFamily(TYPE_RSS_LINK_ACTION.fontFamily)
        .fontWeight(TYPE_RSS_LINK_ACTION.fontWeight)
        .fontSize(TYPE_RSS_LINK_ACTION.fontSizeFp)
        .fontColor(readerAppColor('TOK_PRIMARY_TEXT', this.appThemeScheme))
        .textAlign(TextAlign.Center)
        .backgroundColor(readerAppColor('TOK_PRIMARY_SOFT', this.appThemeScheme))
        .borderRadius(999)
        .responseRegion({ x: 0, y: -8, width: '100%', height: 44 })
        .onClick((): void => this.onViewSource());
    }
    .width('100%')
    .height(58)
    .padding({ left: TOK_SPACE_CONTROL_INLINE, right: TOK_SPACE_CONTROL_INLINE })
    .alignItems(VerticalAlign.Center)
    .backgroundColor(readerAppColor('TOK_CARD_BG_HI', this.appThemeScheme))
    .border({ width: TOK_BORDER_W, color: readerAppColor('app.RssEntryDetailPage.CARD_BORDER', this.appThemeScheme) })
    .borderRadius(8);
  }

private itemMeta(): string {
    const parts: string[] = [];
    if (this.item.pubDate !== undefined && this.item.pubDate !== '') {
      parts.push(this.item.pubDate);
    }
    if (this.item.author !== undefined && this.item.author !== '') {
      parts.push(this.item.author);
    }
    return parts.join(' · ');
  }
